def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = item / bins
    score = np.exp(utilization) - np.exp(1.0 - remaining / bins)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    utilization = 1.0 - (remaining / bins)
    score = np.log1p(utilization) * np.tanh(remaining)
    return np.where(remaining >= 0, score, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    score = -np.exp(-((remaining - 2 * item) ** 2) / (2 * (item ** 2 + 1e-8)))
