def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fraction_remaining = remaining / bins
    score = -np.exp(-fraction_remaining) + 1.0 / (1.0 + np.exp(-10.0 * (item / bins - 0.5)))
    return np.where(remaining >= 0, score, -np.inf)
